class AsyncQueue {
  #items = [];  #waiters = [];
  get() {                                   // suspends the task, not the thread
    if (this.#items.length) return Promise.resolve(this.#items.shift());
    return new Promise(resolve => this.#waiters.push(resolve));
  }
  put(item) {                               // change state first, then resolve
    const resolve = this.#waiters.shift();
    if (resolve) resolve(item); else this.#items.push(item);
  }
}
